"""AIGC 显式标识写入导出产物（修复）。

依据生成式内容标识的通行要求（如中国《人工智能生成合成内容标识办法》、
欧盟 AI Act 透明度义务），在导出音频文件中写入机器可读 + 人可读的
AI 生成标识 metadata：

- MP3：文件头前插 ID3v2.4 —— TXXX 帧自定义键 AIGC + COMM 注释帧
- WAV：RIFF 头部 WAVE 后插 LIST INFO 块 —— ICMT（comment）与 INAM（标题）

纯手写二进制（lameenc 不支持 tag，避免引入 mutagen 依赖）；对无法解析
的字节流原样返回（标识失败不阻断导出，由调用方记日志）。
"""
from __future__ import annotations

AIGC_MARK_TEXT = (
    "AI-generated by Meloyu (AI-assisted music creation). "
    "This audio was generated with AI; see the Meloyu certificate for provenance."
)
AIGC_MARK_KEY = "AIGC"


def _mark_text(attribution: str | None = None) -> str:
    """标识文案；带引擎署名时附加（③：如 "using MiniMax-Music3 (self-hosted)"）。"""
    if not attribution:
        return AIGC_MARK_TEXT
    return (f"AI-generated by Meloyu using {attribution} (AI-assisted music "
            f"creation). This audio was generated with AI; see the Meloyu "
            f"certificate for provenance.")


def _syncsafe(size: int) -> bytes:
    """ID3v2 syncsafe 整数（7bit/字节，4 字节）。"""
    return bytes([(size >> 21) & 0x7F, (size >> 14) & 0x7F,
                  (size >> 7) & 0x7F, size & 0x7F])


def _id3_text_frame(frame_id: str, text: str) -> bytes:
    """单文本帧（encoding=0 ISO-8859-1；标识文本为纯 ASCII，非 ASCII 以 ? 替换）。"""
    payload = b"\x00" + text.encode("ascii", errors="replace")
    return (frame_id.encode("ascii") + _syncsafe(len(payload)) + b"\x00\x00" + payload)


def _id3_txxx_frame(description: str, text: str) -> bytes:
    payload = (b"\x00" + description.encode("ascii") + b"\x00"
               + text.encode("ascii", errors="replace"))
    return b"TXXX" + _syncsafe(len(payload)) + b"\x00\x00" + payload


def id3v2_tag(attribution: str | None = None) -> bytes:
    """完整 ID3v2.4 tag：TXXX(AIGC) + COMM 双标识帧（可含引擎署名）。"""
    text = _mark_text(attribution)
    frames = (_id3_txxx_frame(AIGC_MARK_KEY, text)
              + _id3_text_frame("TIT3", "AI-generated content"))
    comm_payload = b"\x00" + b"eng" + b"AIGC\x00" + text.encode("ascii",
                                                                errors="replace")
    frames += b"COMM" + _syncsafe(len(comm_payload)) + b"\x00\x00" + comm_payload
    return b"ID3" + b"\x04\x00" + b"\x00" + _syncsafe(len(frames)) + frames


def mark_mp3(data: bytes, attribution: str | None = None) -> bytes:
    """MP3 字节流前插 ID3v2 标识 tag（已有 ID3v2 时在其后追加，不破坏原 tag）。"""
    tag = id3v2_tag(attribution)
    if data[:3] == b"ID3":
        # 已有 tag：解析其长度，插在其后（ID3v2 支持多 tag 串联，读取器取并集）
        size = ((data[6] & 0x7F) << 21) | ((data[7] & 0x7F) << 14) | \
               ((data[8] & 0x7F) << 7) | (data[9] & 0x7F)
        end = 10 + size
        return data[:end] + tag + data[end:]
    return tag + data


def mark_wav(data: bytes, attribution: str | None = None) -> bytes:
    """WAV 字节流注入 RIFF LIST INFO 块（ICMT/INAM，可含引擎署名）；
    非标准 RIFF 原样返回。"""
    if len(data) < 12 or data[:4] != b"RIFF" or data[8:12] != b"WAVE":
        return data

    def chunk(chunk_id: bytes, payload: bytes) -> bytes:
        body = chunk_id + len(payload).to_bytes(4, "little") + payload
        if len(payload) % 2:  # RIFF 块按 2 字节对齐
            body += b"\x00"
        return body

    def info_item(item_id: bytes, text: str) -> bytes:
        raw = text.encode("ascii")
        return item_id + len(raw).to_bytes(4, "little") + raw + (b"\x00" if len(raw) % 2 else b"")

    info_payload = (b"INFO"
                    + info_item(b"ICMT", _mark_text(attribution))
                    + info_item(b"INAM", "AI-generated content"))
    list_chunk = chunk(b"LIST", info_payload)
    # 原文件除 RIFF 头（12B）外的全部块保留，LIST 插在最前；RIFF 总长重算
    rest = data[12:]
    new_size = 4 + len(list_chunk) + len(rest)
    return (b"RIFF" + new_size.to_bytes(4, "little") + b"WAVE" + list_chunk + rest)
